css:
.ra-art{--up:#E5484D;--down:#12A366;--acc:#D9A441;--mono:ui-monospace,"SF Mono",Menlo,Consolas,"Roboto Mono",monospace;
--sans:system-ui,-apple-system,"Noto Sans TC","PingFang TC","Microsoft JhengHei",sans-serif}
[data-theme="dark"] .ra-art{--bg:#000;--surface:#111;--raise:#1E1E1E;--ink-1:#F5F5F5;--ink-2:#A3A3A3;--ink-3:#666;--line:#2A2A2A;
--ra-s:#5f9d7a;--ra-b:#e0a93f;--ra-x:#7f93a8;--ra-tr:#8fb8b3;--ra-neg:#c0786a;--ra-hl:#E5484D}
[data-theme="light"] .ra-art{--bg:#F4F6F4;--surface:#FFF;--raise:#EDF0EE;--ink-1:#0F161D;--ink-2:#44515E;--ink-3:#68757F;--line:#DDE3E0;
--ra-s:#3f6b52;--ra-b:#c48b1f;--ra-x:#5d7287;--ra-tr:#3f8b84;--ra-neg:#8a5348;--ra-hl:#C9373C}
.ra-art *{box-sizing:border-box}
.ra-art{-webkit-text-size-adjust:100%}
.ra-art{color:var(--ink-1);font-family:var(--sans);font-size:16px;line-height:1.7}
.ra-art .ra-wrap{max-width:860px;margin:0 auto;padding:0 16px 48px}
.ra-art .ra-pv-x{background:var(--raise);color:var(--ink-2);font-size:13px;padding:8px 16px;text-align:center}
.ra-art h1{font-size:26px;line-height:1.35;margin:28px 0 6px}
.ra-art .ra-sub{color:var(--ink-2);font-size:14.5px;margin:0 0 6px}
.ra-art .ra-disc{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:1px 10px;font-size:12.5px;color:var(--ink-2)}
.ra-art h2{font-size:21px;margin:40px 0 8px;padding-top:14px;border-top:1px solid var(--line)}
.ra-art h3{font-size:16.5px;margin:22px 0 6px}
.ra-art p{margin:8px 0}
.ra-art .ra-lede{font-size:16.5px}
.ra-art .ra-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin:14px 0}
.ra-art .ra-kpi{background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:10px 12px;min-width:0}
.ra-art .ra-kpi b{display:block;font-family:var(--mono);font-size:22px;font-weight:600;letter-spacing:-.02em}
.ra-art .ra-kpi span{color:var(--ink-2);font-size:12.5px;line-height:1.45;display:block}
.ra-art .ra-fig{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:12px 12px 8px;margin:14px 0}
.ra-art .ra-fig figcaption{font-size:14px;font-weight:600;margin:0 0 6px}
.ra-art .ra-fig .ra-cap2{font-size:12.5px;color:var(--ink-2);font-weight:400;margin:6px 0 0}
.ra-art .ra-svg{width:100%;max-width:680px;height:auto;display:block;margin:0 auto}
.ra-art .ra-svg .t,.ra-art .ra-svg .ra-ax{fill:var(--ink-2);font-size:12px;font-family:var(--sans)}
.ra-art .ra-svg .ra-lg{fill:var(--ink-1);font-size:12.5px}
.ra-art .ra-svg .ra-vl{fill:var(--ink-2);font-size:10.5px;font-family:var(--mono)}
.ra-art .ra-svg .ra-pl{fill:var(--ink-2);font-size:12px;font-family:var(--mono)}
.ra-art .ra-svg .ra-pl-hl{fill:var(--ra-hl);font-size:13px;font-weight:700;font-family:var(--mono)}
.ra-art .ra-svg .ra-r{fill:var(--ink-1);font-size:13px;font-weight:600}
.ra-art .ra-grid{stroke:var(--line);stroke-width:1}
.ra-art .ra-zero{stroke:var(--ink-3);stroke-width:1}
.ra-art .ra-fit{stroke:var(--ra-b);stroke-width:2;stroke-dasharray:6 4}
.ra-art .ra-dot{fill:var(--ra-s);opacity:.9}
.ra-art .ra-dot-hl{fill:var(--ra-hl)}
.ra-art .ra-s{fill:var(--ra-s)}
.ra-art .ra-b{fill:var(--ra-b)}
.ra-art .ra-x{fill:var(--ra-x)}
.ra-art .ra-tr{fill:var(--ra-tr)}
.ra-art .ra-negfill{fill:var(--ra-neg)}
.ra-art .ra-line{fill:none;stroke-width:1.6;stroke-linejoin:round}
.ra-art .ra-line.ra-s{stroke:var(--ra-s);fill:none}
.ra-art .ra-line.ra-thick{stroke-width:3.4}
.ra-art .ra-line.ra-dash{stroke-dasharray:7 5;stroke-width:2}
.ra-art .ra-line.ra-hlc{stroke:var(--ra-hl);fill:none}
.ra-art .ra-line.ra-b{stroke:var(--ra-b);fill:none}
.ra-art .ra-line.ra-x{stroke:var(--ra-x);fill:none}
.ra-art .ra-line.ra-tr{stroke:var(--ra-tr);fill:none}
.ra-art .ra-tw{overflow-x:auto;-webkit-overflow-scrolling:touch;margin:10px 0;border:1px solid var(--line);border-radius:10px}
.ra-art table{border-collapse:collapse;width:100%;font-size:13.5px;background:var(--surface)}
.ra-art th,.ra-art td{padding:6px 8px;border-bottom:1px solid var(--line);text-align:right;white-space:nowrap}
.ra-art th{color:var(--ink-2);font-weight:600;font-size:12.5px;background:var(--raise)}
.ra-art td:first-child,.ra-art th:first-child{text-align:left}
.ra-art td{font-family:var(--mono);font-variant-numeric:tabular-nums}
.ra-art tr.ra-hlrow td{background:rgba(229,72,77,.09)}
.ra-art .pos{color:var(--ra-s)}
.ra-art .neg{color:var(--ra-neg)}
.ra-art .ra-note{background:var(--raise);border-radius:10px;padding:10px 14px;font-size:14px;color:var(--ink-2);margin:12px 0}
.ra-art .ra-note b{color:var(--ink-1)}
.ra-art .ra-big{border-left:3px solid var(--ra-b);padding:4px 0 4px 12px;margin:14px 0;font-size:16px}
.ra-art details{margin:10px 0}
.ra-art summary{cursor:pointer;color:var(--ink-2);font-size:14px}
.ra-art .ra-src{font-size:12.5px;color:var(--ink-2);line-height:1.65}
.ra-art .ra-src code{font-family:var(--mono);font-size:12px;word-break:break-all}
.ra-art .ra-theme-x{border:1px solid var(--line);background:var(--surface);color:var(--ink-1);border-radius:999px;padding:2px 10px;font-size:12.5px;cursor:pointer;margin-left:8px}
@media (max-width:600px){.ra-art .ra-svg .t,.ra-art .ra-svg .ra-ax{font-size:18px}
.ra-art .ra-svg .ra-lg{font-size:18px}
.ra-art .ra-svg .ra-vl{display:none}
.ra-art .ra-svg .ra-pl{font-size:17px}
.ra-art .ra-svg .ra-pl-hl{font-size:19px}
.ra-art .ra-svg .ra-r{font-size:19px}
.ra-art .ra-fig{padding:10px 6px 8px}}
@media (max-width:480px){.ra-art h1{font-size:22px}
.ra-art h2{font-size:19px}
.ra-art .ra-kpi b{font-size:19px}
.ra-art table{font-size:12.5px}
.ra-art th,.ra-art td{padding:5px 6px}}
